head.script:
scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 Group 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';        
    strGenerator += '<w2:tabControl id="generator1_child" alwaysDraw="false" style="width:500px;height:200px;" ev:onclick="scwin.generator1_child_onclick">';
    strGenerator += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strGenerator += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strGenerator += '<w2:content alwaysDraw="false" style="height:160px;" id="content1">';
    strGenerator += '<w2:button style="width:80px; height:23px; " id="" label="tabs1"></w2:button>';
    strGenerator += '</w2:content>';
    strGenerator += '<w2:content alwaysDraw="false" style="height:160px" id="content2">';
    strGenerator += '<xf:input id="" style="width:144px; height:21px; " initValue="tabs2"></xf:input>';
    strGenerator += '</w2:content>';
    strGenerator += '</w2:tabControl>';
    strGenerator += '</w2:generator>';

    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp    
    );

    scwin.generator1.insertChild();

    // Generator 컴포넌트의 자식이 아닌 컴포넌트 생성
    $c.gcm.createBasicTabControl('', 'ev:onclick="scwin.target1_onclick"');
}
